<?php
class Cache { private static $cacheDir = __DIR__ . '/../../cache/'; public static function init() { if (!is_dir(self::$cacheDir)) { mkdir(self::$cacheDir, 0777, true); } } public static function get($key, $ttlSeconds = 3600) { self::init(); $safeKey = md5($key); $file = self::$cacheDir . $safeKey . '.cache'; if (file_exists($file)) { if (time() - filemtime($file) < $ttlSeconds) { $data = file_get_contents($file); if ($data !== false) { $decoded = @json_decode($data, true); if ($decoded !== null) { return $decoded; } } } else { @unlink($file); } } return false; } public static function set($key, $data) { self::init(); $safeKey = md5($key); $file = self::$cacheDir . $safeKey . '.cache'; $encoded = json_encode($data); if ($encoded) { file_put_contents($file, $encoded, LOCK_EX); } } public static function flush() { self::init(); $files = glob(self::$cacheDir . '*.cache'); foreach ($files as $file) { if (is_file($file)) { @unlink($file); } } } }